CREATE OR REPLACE FUNCTION public.actualizar_datos_facturacion(p_rfc text DEFAULT NULL::text, p_razon_social text DEFAULT NULL::text, p_regimen_fiscal text DEFAULT NULL::text, p_codigo_postal_fiscal text DEFAULT NULL::text, p_uso_cfdi text DEFAULT NULL::text, p_correo_facturacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_auth_user_id uuid;
  v_usuario public.usuarios%rowtype;
  v_empresa_actualizada boolean := false;
  v_rfc text;
  v_razon_social text;
  v_regimen_fiscal text;
  v_codigo_postal_fiscal text;
  v_uso_cfdi text;
  v_correo_facturacion text;
begin
  v_auth_user_id := auth.uid();
  if v_auth_user_id is null then
    raise exception 'Sin sesión activa' using errcode = '42501';
  end if;

  select * into v_usuario
  from public.usuarios
  where auth_user_id = v_auth_user_id
  for update;

  if not found then
    raise exception 'Usuario no encontrado' using errcode = 'P0002';
  end if;

  v_rfc := nullif(trim(p_rfc), '');
  v_razon_social := nullif(trim(p_razon_social), '');
  v_regimen_fiscal := nullif(trim(p_regimen_fiscal), '');
  v_codigo_postal_fiscal := nullif(trim(p_codigo_postal_fiscal), '');
  v_uso_cfdi := nullif(trim(p_uso_cfdi), '');
  v_correo_facturacion := nullif(trim(p_correo_facturacion), '');

  -- 1. Actualizar datos fiscales en usuarios
  update public.usuarios
  set
    rfc = v_rfc,
    razon_social = v_razon_social,
    regimen_fiscal = v_regimen_fiscal,
    codigo_postal_fiscal = v_codigo_postal_fiscal,
    uso_cfdi = v_uso_cfdi,
    correo_facturacion = v_correo_facturacion
  where id = v_usuario.id;

  -- 2. Si el usuario es titular de empresa, actualizar conjuntamente en empresas
  if v_usuario.empresa_id is not null and v_usuario.rol = 'titular_empresa' then
    update public.empresas
    set
      rfc = v_rfc,
      razon_social = v_razon_social,
      regimen_fiscal = v_regimen_fiscal,
      codigo_postal_fiscal = v_codigo_postal_fiscal,
      uso_cfdi = v_uso_cfdi,
      correo_facturacion = v_correo_facturacion
    where id = v_usuario.empresa_id;

    v_empresa_actualizada := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'usuario_id', v_usuario.id,
    'empresa_id', v_usuario.empresa_id,
    'empresa_actualizada', v_empresa_actualizada
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.manejar_nuevo_usuario_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tipo_registro text:=new.raw_user_meta_data->>'tipo_registro';
  v_version_registro integer:=coalesce(nullif(new.raw_user_meta_data->>'version_registro','')::integer,1);
  v_solicitud_id uuid;
begin
  if v_tipo_registro='conductor' then
    insert into public.solicitudes_conductor(
      auth_user_id,estado,paso_actual,datos_personales,domicilio,licencia,contacto_emergencia,version_registro,origen_modelo
    ) values(
      new.id,'borrador',0,'{}','{}','{}','{}',v_version_registro,
      case when v_version_registro=2 then 'v2_minimo' else 'legacy_metadata' end
    ) returning id into v_solicitud_id;
    insert into public.registro_auditoria(evento,actor,actor_id,datos)
    values('creacion_cuenta','conductor',v_solicitud_id,jsonb_build_object(
      'auth_user_id',new.id,'tipo_registro','conductor','version_registro',v_version_registro));
  elsif v_tipo_registro='usuario' then
    perform public.crear_usuario_legacy_desde_auth(new);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.procesar_competencias_asignacion()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_procesadas integer := 0;
  v_asignadas integer := 0;
  v_puntualidades integer := 0;
begin
  v_puntualidades := private.confirmar_puntualidad_vencida();
  for v_id in
    select c.id from public.competencias_asignacion c
    where c.estado = 'abierta' and c.cierra_en <= now()
    order by c.cierra_en
    limit 50
    for update skip locked
  loop
    v_procesadas := v_procesadas + 1;
    if private.resolver_competencia_asignacion(v_id) then
      v_asignadas := v_asignadas + 1;
    end if;
  end loop;
  return jsonb_build_object('procesadas', v_procesadas, 'asignadas', v_asignadas,
    'puntualidades_confirmadas', v_puntualidades);
end;
$function$

CREATE OR REPLACE FUNCTION public.proteger_verificacion_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.es_admin() then
    return new;
  end if;

  if auth.uid() is null or auth.uid() is distinct from old.auth_user_id then
    return new;
  end if;

  if new.auth_user_id is distinct from old.auth_user_id
    or new.tipo_cuenta is distinct from old.tipo_cuenta
    or new.rol is distinct from old.rol
    or new.empresa_id is distinct from old.empresa_id
    or new.traslados_completados_sin_incidencia is distinct from old.traslados_completados_sin_incidencia
    or new.metodo_pago_registrado is distinct from old.metodo_pago_registrado
    or new.creado_en is distinct from old.creado_en then
    raise exception 'No puedes modificar campos administrativos de la cuenta.';
  end if;

  if coalesce(current_setting('ruum.cambio_documento_identidad_autorizado', true), '') <> 'si'
    and (
      new.doc_identidad_url is distinct from old.doc_identidad_url
      or new.doc_identidad_subido_en is distinct from old.doc_identidad_subido_en
      or new.estado_verificacion is distinct from old.estado_verificacion
    ) then
    raise exception 'Los campos de verificación sólo pueden modificarse mediante el flujo autorizado.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_documento_identidad(p_sello_id uuid, p_ruta text, p_sha256 text)
 RETURNS TABLE(ruta text, estado text, subido_en timestamp with time zone, ruta_anterior text, documento_id uuid, version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
declare
  v_auth uuid := auth.uid();
  v_usuario public.usuarios;
  v_sello public.documentos_identidad_storage_validados;
  v_anterior public.documentos_identidad_usuario;
  v_nuevo_id uuid;
  v_version integer;
  v_subido_en timestamptz := now();
begin
  if v_auth is null then raise exception 'Inicia sesión para registrar tu documento de identidad.'; end if;
  select * into v_usuario from public.usuarios u where u.auth_user_id = v_auth for update;
  if v_usuario.id is null then raise exception 'No se encontró el perfil del usuario autenticado.'; end if;

  select * into v_sello from public.documentos_identidad_storage_validados s
  where s.id = p_sello_id for update;
  if v_sello.id is null then raise exception 'El sello de validación no existe.'; end if;
  if v_sello.auth_user_id <> v_auth or v_sello.usuario_id <> v_usuario.id then
    raise exception 'El sello no pertenece al usuario autenticado.';
  end if;
  if v_sello.consumido_en is not null then raise exception 'El sello de validación ya fue consumido.'; end if;
  if v_sello.expira_en <= now() then raise exception 'El sello de validación está vencido.'; end if;
  if v_sello.ruta <> p_ruta or v_sello.sha256 <> lower(p_sha256) then
    raise exception 'La ruta o el hash no coinciden con el sello validado.';
  end if;
  if not exists(select 1 from storage.objects o where o.bucket_id = 'documentos-identidad' and o.name = p_ruta) then
    raise exception 'El archivo validado no existe en Storage.';
  end if;

  select * into v_anterior from public.documentos_identidad_usuario d
  where d.usuario_id = v_usuario.id and d.es_actual for update;
  v_version := coalesce(v_anterior.version, 0) + 1;
  if v_anterior.id is not null then
    update public.documentos_identidad_usuario set
      es_actual = false, estado = 'reemplazado', reemplazado_en = v_subido_en
    where id = v_anterior.id;
  end if;

  insert into public.documentos_identidad_usuario(
    usuario_id, sello_id, ruta, sha256, mime, tamano_bytes, version, documento_anterior_id, creado_en
  ) values (
    v_usuario.id, v_sello.id, v_sello.ruta, v_sello.sha256, v_sello.mime,
    v_sello.tamano_bytes, v_version, v_anterior.id, v_subido_en
  ) returning id into v_nuevo_id;

  update public.documentos_identidad_storage_validados set consumido_en = v_subido_en where id = v_sello.id;
  perform set_config('ruum.cambio_documento_identidad_autorizado', 'si', true);
  update public.usuarios set doc_identidad_url = p_ruta,
    doc_identidad_subido_en = v_subido_en, estado_verificacion = 'en_revision'
  where id = v_usuario.id;
  perform set_config('ruum.cambio_documento_identidad_autorizado', '', true);

  insert into public.registro_auditoria(evento, actor, actor_id, datos)
  values ('carga_documento_identidad', 'usuario', v_usuario.id, jsonb_build_object(
    'documento_id', v_nuevo_id, 'fecha', v_subido_en, 'sha256', v_sello.sha256,
    'mime_detectado', v_sello.mime, 'tamano_bytes', v_sello.tamano_bytes,
    'version', v_version, 'estado', 'en_revision', 'origen', 'edge_function',
    'documento_anterior_id', v_anterior.id, 'ruta_anterior', v_anterior.ruta
  ));

  return query select p_ruta, 'en_revision'::text, v_subido_en, v_anterior.ruta, v_nuevo_id, v_version;
end;
$function$
